CREATE SCHEMA IF NOT EXISTS app;
CREATE SCHEMA IF NOT EXISTS sync;

CREATE TABLE IF NOT EXISTS sync."OfflineAccessPermit"
(
    "OfflineAccessPermitId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OfflineAccessPermitGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "DeviceGuid" UUID NOT NULL,
    "UserId" BIGINT NOT NULL,
    "UserGuid" UUID NOT NULL,
    "CompanyId" BIGINT NOT NULL,
    "CompanyOfficeId" BIGINT,
    "AppCode" VARCHAR(80) NOT NULL,
    "CanCapture" BOOLEAN NOT NULL DEFAULT TRUE,
    "CanVerify" BOOLEAN NOT NULL DEFAULT FALSE,
    "PermissionVersion" INT NOT NULL DEFAULT 1,
    "IssuedAt" TIMESTAMPTZ NOT NULL,
    "ExpiresAt" TIMESTAMPTZ NOT NULL,
    "RevokedTime" TIMESTAMPTZ,
    "PermitJson" JSONB NOT NULL,
    "StatusId" INT NOT NULL DEFAULT 1,
    "RowVersion" BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_OfflineAccessPermit_OfflineAccessPermitGuid" UNIQUE ("OfflineAccessPermitGuid")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_OfflineAccessPermit_DeviceUserApp_Active"
    ON sync."OfflineAccessPermit" ("DeviceGuid", "UserId", "AppCode")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0 AND "RevokedTime" IS NULL);

CREATE INDEX IF NOT EXISTS "IX_OfflineAccessPermit_UserId"
    ON sync."OfflineAccessPermit" ("UserId");

CREATE INDEX IF NOT EXISTS "IX_OfflineAccessPermit_CompanyId"
    ON sync."OfflineAccessPermit" ("CompanyId");

CREATE TABLE IF NOT EXISTS app."InventoryItem"
(
    "InventoryItemId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InventoryItemGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "CompanyId" BIGINT NOT NULL,
    "CompanyOfficeId" BIGINT,
    "ItemCode" VARCHAR(50) NOT NULL,
    "ItemName" VARCHAR(200) NOT NULL,
    "Barcode" VARCHAR(80) NOT NULL,
    "UnitOfMeasure" VARCHAR(20) NOT NULL,
    "StatusId" INT NOT NULL DEFAULT 1,
    "RowVersion" BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_InventoryItem_InventoryItemGuid" UNIQUE ("InventoryItemGuid")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_InventoryItem_CompanyBarcode_Active"
    ON app."InventoryItem" ("CompanyId", "Barcode")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

CREATE INDEX IF NOT EXISTS "IX_InventoryItem_CompanyId"
    ON app."InventoryItem" ("CompanyId");

CREATE INDEX IF NOT EXISTS "IX_InventoryItem_CompanyOfficeId"
    ON app."InventoryItem" ("CompanyOfficeId");

CREATE TABLE IF NOT EXISTS app."PhysicalInventoryDocument"
(
    "PhysicalInventoryDocumentId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PhysicalInventoryDocumentGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "CompanyId" BIGINT NOT NULL,
    "CompanyOfficeId" BIGINT,
    "DocumentNumber" VARCHAR(50) NOT NULL,
    "CountDate" DATE NOT NULL,
    "DocumentStatus" VARCHAR(40) NOT NULL DEFAULT 'Open',
    "StatusId" INT NOT NULL DEFAULT 1,
    "RowVersion" BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_PhysicalInventoryDocument_PhysicalInventoryDocumentGuid" UNIQUE ("PhysicalInventoryDocumentGuid")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_PhysicalInventoryDocument_CompanyNumber_Active"
    ON app."PhysicalInventoryDocument" ("CompanyId", "DocumentNumber")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

CREATE INDEX IF NOT EXISTS "IX_PhysicalInventoryDocument_CompanyOfficeId"
    ON app."PhysicalInventoryDocument" ("CompanyOfficeId");

CREATE TABLE IF NOT EXISTS app."PhysicalInventoryDocumentPage"
(
    "PhysicalInventoryDocumentPageId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PhysicalInventoryDocumentPageGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "PhysicalInventoryDocumentId" BIGINT NOT NULL,
    "PageNumber" INT NOT NULL,
    "PageStatus" VARCHAR(40) NOT NULL DEFAULT 'Open',
    "AssignedUserId" BIGINT,
    "StatusId" INT NOT NULL DEFAULT 1,
    "RowVersion" BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_PhysicalInventoryDocumentPage_PhysicalInventoryDocumentPageGuid" UNIQUE ("PhysicalInventoryDocumentPageGuid")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_PhysicalInventoryDocumentPage_DocumentPage_Active"
    ON app."PhysicalInventoryDocumentPage" ("PhysicalInventoryDocumentId", "PageNumber")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

CREATE INDEX IF NOT EXISTS "IX_PhysicalInventoryDocumentPage_PhysicalInventoryDocumentId"
    ON app."PhysicalInventoryDocumentPage" ("PhysicalInventoryDocumentId");

CREATE TABLE IF NOT EXISTS app."PhysicalInventoryExpectedLine"
(
    "PhysicalInventoryExpectedLineId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PhysicalInventoryExpectedLineGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "PhysicalInventoryDocumentPageId" BIGINT NOT NULL,
    "InventoryItemId" BIGINT NOT NULL,
    "ExpectedQuantity" DECIMAL(18,4) NOT NULL,
    "StatusId" INT NOT NULL DEFAULT 1,
    "RowVersion" BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_PhysicalInventoryExpectedLine_PhysicalInventoryExpectedLineGuid" UNIQUE ("PhysicalInventoryExpectedLineGuid")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_PhysicalInventoryExpectedLine_PageItem_Active"
    ON app."PhysicalInventoryExpectedLine" ("PhysicalInventoryDocumentPageId", "InventoryItemId")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

CREATE INDEX IF NOT EXISTS "IX_PhysicalInventoryExpectedLine_InventoryItemId"
    ON app."PhysicalInventoryExpectedLine" ("InventoryItemId");

CREATE TABLE IF NOT EXISTS app."PhysicalInventoryCapture"
(
    "PhysicalInventoryCaptureId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PhysicalInventoryCaptureGuid" UUID NOT NULL,
    "CompanyId" BIGINT NOT NULL,
    "CompanyOfficeId" BIGINT,
    "DeviceGuid" UUID NOT NULL,
    "OperationGuid" UUID NOT NULL,
    "DocumentNumber" VARCHAR(50) NOT NULL,
    "PageNumber" INT NOT NULL,
    "PhysicalInventoryDocumentId" BIGINT,
    "PhysicalInventoryDocumentPageId" BIGINT,
    "CounterUserId" BIGINT NOT NULL,
    "CounterUserGuid" UUID NOT NULL,
    "CaptureStatus" VARCHAR(40) NOT NULL,
    "PayloadHash" VARCHAR(64) NOT NULL,
    "ConcurrencyToken" BIGINT NOT NULL DEFAULT 1,
    "StartedAt" TIMESTAMPTZ NOT NULL,
    "FinishedAt" TIMESTAMPTZ NOT NULL,
    "UploadedAt" TIMESTAMPTZ NOT NULL,
    "VerifiedById" BIGINT,
    "VerifiedAt" TIMESTAMPTZ,
    "VerificationNote" VARCHAR(500),
    "StatusId" INT NOT NULL DEFAULT 1,
    "RowVersion" BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_PhysicalInventoryCapture_PhysicalInventoryCaptureGuid" UNIQUE ("PhysicalInventoryCaptureGuid"),
    CONSTRAINT "UQ_PhysicalInventoryCapture_OperationGuid" UNIQUE ("OperationGuid")
);

CREATE INDEX IF NOT EXISTS "IX_PhysicalInventoryCapture_CompanyStatus"
    ON app."PhysicalInventoryCapture" ("CompanyId", "CaptureStatus")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

CREATE INDEX IF NOT EXISTS "IX_PhysicalInventoryCapture_DocumentPage"
    ON app."PhysicalInventoryCapture" ("CompanyId", "DocumentNumber", "PageNumber");

CREATE TABLE IF NOT EXISTS app."PhysicalInventoryCaptureLine"
(
    "PhysicalInventoryCaptureLineId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PhysicalInventoryCaptureLineGuid" UUID NOT NULL DEFAULT gen_random_uuid(),
    "PhysicalInventoryCaptureId" BIGINT NOT NULL,
    "Barcode" VARCHAR(80) NOT NULL,
    "CountedQuantity" DECIMAL(18,4) NOT NULL,
    "ScanCount" INT NOT NULL DEFAULT 1,
    "Source" VARCHAR(20) NOT NULL,
    "InventoryItemId" BIGINT,
    "ExpectedQuantity" DECIMAL(18,4),
    "Variance" DECIMAL(18,4),
    "ValidationResult" VARCHAR(40) NOT NULL,
    "FirstCapturedAt" TIMESTAMPTZ NOT NULL,
    "LastCapturedAt" TIMESTAMPTZ NOT NULL,
    "StatusId" INT NOT NULL DEFAULT 1,
    "RowVersion" BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById" BIGINT NOT NULL DEFAULT 0,
    "CreatedTime" TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById" BIGINT,
    "UpdatedTime" TIMESTAMPTZ,
    "DeletedById" BIGINT,
    "DeletedTime" TIMESTAMPTZ,
    CONSTRAINT "UQ_PhysicalInventoryCaptureLine_PhysicalInventoryCaptureLineGuid" UNIQUE ("PhysicalInventoryCaptureLineGuid")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_PhysicalInventoryCaptureLine_CaptureBarcode_Active"
    ON app."PhysicalInventoryCaptureLine" ("PhysicalInventoryCaptureId", "Barcode")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

CREATE INDEX IF NOT EXISTS "IX_PhysicalInventoryCaptureLine_InventoryItemId"
    ON app."PhysicalInventoryCaptureLine" ("InventoryItemId");
